CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,password_hash TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS categories (id SERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,name VARCHAR(80) NOT NULL,color VARCHAR(20) NOT NULL DEFAULT '#10b981');
CREATE UNIQUE INDEX IF NOT EXISTS categories_user_name_idx ON categories(user_id,name) WHERE user_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS categories_global_name_idx ON categories(name) WHERE user_id IS NULL;
CREATE TABLE IF NOT EXISTS expenses (id BIGSERIAL PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,category_id INTEGER NOT NULL REFERENCES categories(id) ON DELETE RESTRICT,amount NUMERIC(12,2) NOT NULL CHECK(amount>0),spent_on DATE NOT NULL DEFAULT CURRENT_DATE,description VARCHAR(500) NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS expenses_user_date_idx ON expenses(user_id,spent_on DESC,id DESC);
CREATE INDEX IF NOT EXISTS expenses_category_idx ON expenses(category_id);
